typedef unsigned int u_int;

struct nglTexture;
struct nglMaterialInfo;
struct nglFixedString { char data[32]; };

struct nglMaterial {
  u_int Flags;
  nglTexture* Map;
  nglTexture* LightMap;
  nglTexture* DetailMap;
  nglTexture* EnvironmentMap;
  u_int Pad0;
  nglFixedString MapName;
  int MapBlendMode;
  int MapBlendModeConstant;
  nglFixedString LightMapName;
  int LightMapBlendMode;
  int LightMapBlendModeConstant;
  nglFixedString DetailMapName;
  int DetailMapBlendMode;
  int DetailMapBlendModeConstant;
  float DetailMapUScale;
  float DetailMapVScale;
  float DetailMapRange;
  float DetailMapAlphaClamp;
  nglFixedString EnvironmentMapName;
  int EnvironmentMapBlendMode;
  int EnvironmentMapBlendModeConstant;
  u_int SpecularColor;
  float SpecularPower;
  float SpecularIntensity;
  u_int Color;
  u_int MaterialID;
  float AlphaFalloff;
  float ForcedSortDistance;
  float ScrollU, ScrollV;
  nglMaterialInfo* Info;
  float MapMipRatio;
  float LightMapMipRatio;
  u_int UserFlags;
  u_int Pad[2];
};

struct nglMeshBatchInfo {
  u_int NVerts;
  u_int* StripData;
  float* PosData;
  float* UVData;
  u_int* ColorData;
  float* NormData;
  float* LightUVData;
  char* BoneCountData;
  unsigned short* BoneIdxData;
  float* BoneWeightData;
};

struct nglMeshSection {
  nglMaterial* Material;
  u_int NVerts;
  u_int NStrips;
  float SphereRadius;
  char padding[28];
  nglMeshBatchInfo* BatchInfo;
};

struct nglMesh {
  char padding[84];
  u_int NSections;
  nglMeshSection* Sections;
};

struct nglPerfInfoStruct {
  char padding[76];
  u_int ScratchMeshBytesUsed;
};

enum {
  NGLMAT_ALPHA = 0x00000001,
  NGLMAT_TEXTURE_MAP = 0x00000010,
  NGL_TEXTURE_MASK = 0x000000F0,
  NGLBM_OPAQUE = 0,
  NGLBM_PUNCHTHROUGH = 1,
  NGLBM_PUNCHTHROUGH_NO_ZTEST = 8
};

#define NGL_DMA_MEM 0x0fffffff

extern nglMesh* nglScratch;
extern nglMeshSection* nglScratchSection;
extern nglTexture* nglWhiteTex;
extern u_int* nglScratchMeshPos;
extern u_int* nglScratchMeshWork;
extern u_int nglScratchMeshWorkSize;
extern nglMeshBatchInfo nglScratchBatch;
extern int nglScratchBatchIdx;
extern nglPerfInfoStruct nglPerfInfo;

extern "C" void* memcpy(void*, const void*, unsigned int);
void nglFatal(const char*, ...);
void nglBakeMaterial(nglMesh*, nglMeshSection*, bool);
void nglCreateMeshDMA(u_int*&, nglMesh*, nglMeshSection*);

void nglMeshAddSection( nglMaterial* Material, u_int NVerts, u_int NStrips )
{
  nglScratchSection++;
  if ( (u_int)( nglScratchSection - nglScratch->Sections ) >= nglScratch->NSections )
    nglFatal( "Added too many sections to a scratch mesh.\n" );

  Material->Info = nglScratchSection->Material->Info;

  // Copy the material and correct some common material mistakes.
  memcpy( nglScratchSection->Material, Material, sizeof(nglMaterial) );

  if ( Material->MapBlendMode != NGLBM_OPAQUE && Material->MapBlendMode != NGLBM_PUNCHTHROUGH &&
       Material->MapBlendMode != NGLBM_PUNCHTHROUGH_NO_ZTEST)
    nglScratchSection->Material->Flags |= NGLMAT_ALPHA;

  if ( !( Material->Flags & NGL_TEXTURE_MASK ) )
  {
    nglScratchSection->Material->Flags |= NGLMAT_TEXTURE_MAP;
    nglScratchSection->Material->Map = nglWhiteTex;
  }

  nglBakeMaterial( nglScratch, nglScratchSection, true );

  // Set up the section with defaults.
  nglScratchSection->NVerts = NVerts;
  nglScratchSection->NStrips = 0;

  nglCreateMeshDMA( nglScratchMeshPos, nglScratch, nglScratchSection );

  memcpy( &nglScratchBatch, nglScratch->Sections->BatchInfo, sizeof(nglMeshBatchInfo) );
  nglScratchBatchIdx = 0;

  // See if the operation overflowed the scratch mesh buffer.
  nglPerfInfo.ScratchMeshBytesUsed = ( (u_int)nglScratchMeshPos & NGL_DMA_MEM ) - (u_int)nglScratchMeshWork;
  if ( nglPerfInfo.ScratchMeshBytesUsed > nglScratchMeshWorkSize )
    nglFatal( "Scratch mesh workspace overflow (%d/%d).\n", nglPerfInfo.ScratchMeshBytesUsed, nglScratchMeshWorkSize );
}
